        for(int mask=0;mask<(1<<question_marks.size());mask++){
            vector<vector<int>> tmp_data=data;
            int ok=1;
            for(int i=0;i<question_marks.size() && ok;i++){
                if(mask&(1<<i)){
                    tmp_data[question_marks[i]/(s+1)][question_marks[i]%(s+1)] = 1;
