const int N = 2e5 + 5;
const int M = 3e5 + 5;

vector<pair<int, int>> adj[N];
bitset<N> active_edge;
int p[N];
int dsu[N], sz[N], max_p[N];

int find(int x) {
    if (dsu[x] == x) return x;
    return dsu[x] = find(dsu[x]);
}

void merge(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    if (sz[x] < sz[y]) swap(x, y);
    dsu[y] = x;
    sz[x] += sz[y];
    if (max_p[x] < max_p[y]) max_p[x] = max_p[y];
}

int main() {
