bool bfs() {
    queue<pair<int, int>> q;
    memset(vis, 0, sizeof(vis));
    for (int j = 1; j <= c; j++) {
        if (grid[1][j] == 0) {
            q.push({1, j});
            vis[1][j] = true;
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (x == r) return true;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (nx < 1 || nx > r || ny < 1 || ny > c || grid[nx][ny] == 1) continue;
            if (vis[nx][ny]) continue;
            vis[nx][ny] = true;
            q.push({nx, ny});
        }
        if (y == 1) {
            int nx = x, ny = c;
            if (grid[nx][ny] == 0 && !vis[nx][ny]) {
                vis[nx][ny] = true;
                q.push({nx, ny});
