void bfs(int src) {
    queue<int> q;
    memset(dis, -1, sizeof dis);
    q.push(src);
    dis[src] = 0;
    int farthestNode = -1, maxDist = -1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (dis[u] > maxDist) {
            maxDist = dis[u];
            farthestNode = u;
        }
        for (auto p : adj[u]) {
            int v = p.first, w = p.second;
            if (dis[v] == -1) {
                dis[v] = dis[u] + w;
                q.push(v);
            }
        }
    }
    farthest[src] = farthestNode;
}

void findDiameter(int src) {
    bfs(src);
    int otherEnd = farthest[src];
    bfs(otherEnd);
    int diameter = dis[farthest[otherEnd]];
    int node = farthest[otherEnd];
    int steps = diameter;
    while (steps > diameter / 2) {
        for (auto p : adj[node]) {
            if (dis[p.first] == dis[node] - p.second) {
                node = p.first;
                break;
            }
        }
        --steps;
    }
    center = node;
    if (diameter % 2 == 0) {
        terminals[0] = node;
        terminals[1] = farthest[node];
    } else {
        terminals[0] = node;
    }
}

void dfs(int u, int p, int d, int &maxd) {
    if (d > maxd) {
        maxd = d;
        farthest[u] = p;
    }
    for (auto &v : adj[u]) {
        if (v.first != p) {
            dfs(v.first, u, d + v.second, maxd);
        }
    }
}

