ld x[N], y[N];

bool check(ld t) {
    for (int i = 0; i < n; ++i) {
        ld nx = x[i] - v * t;
        ld ny = y[i];
        ld nx1 = x[(i + 1) % n] - v * t;
        ld ny1 = y[(i + 1) % n];
        if (nx * ny1 - nx1 * ny < 0) {
            swap(nx, nx1);
            swap(ny, ny1);
        }
        if (nx <= 0 && nx1 >= 0 && ny >= 0 && ny1 <= w && nx * (w - ny) + (ny1 - ny) * (-nx1) + nx1 * (w - ny1) >= 0 && nx * (-ny) + (ny1 - ny) * (nx1) + nx1 * (-ny1) <= 0) {
            return false;
        }
    }
    return true;
}

