bool dfs(int u, int p) {
    vis[u] = 1;
    bool valid = true;
    for (int v : adj[u]) {
        if (v != p) {
            valid &= dfs(v, u);
        }
    }
    if (d[u] == -1) {
        if (deg[u] % 2) {
            valid = false;
        }
    } else {
        if (deg[u] % 2 != d[u]) {
            valid = false;
        }
    }
    return valid;
}

void mark_even(int u, int p) {
    vis[u] = 1;
    for (int v : adj[u]) {
        if (v != p) {
            if (!vis[v]) {
                mark_even(v, u);
            } else {
                if ((deg[u] + deg[v]) % 2 == 1) {
                    deg[u]--;
                    deg[v]--;
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= n; ++i) {
        cin >> d[i];
    }
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        edges.emplace_back(u, v);
        adj[u].push_back(v);
        adj[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }
    bool possible = dfs(1, -1);
    if (!possible) {
        cout << -1;
        return 0;
    }
    for (int i = 1; i <= n; ++i) {
        vis[i] = 0;
    }
    mark_even(1, -1);
    vector<int> ans;
    for (int i = 0; i < m; ++i) {
        int u = edges[i].first, v = edges[i].second;
        if (deg[u] > 0 && deg[v] > 0) {
            deg[u]--;
            deg[v]--;
            ans.push_back(i + 1);
        }
    }
    cout << ans.size() << "\n";
    for (int i = 0; i < ans.size(); ++i) {
        cout << ans[i] << " ";
    }
}

