using namespace std;

void flip(vector<vector<int>>& grid, int r, int c) {
    if (r >= 0 && r < 10 && c >= 0 && c < 10) {
        grid[r][c] = 1 - grid[r][c];
    }
}

void toggle(vector<vector<int>>& grid, int r, int c) {
    flip(grid, r, c);
    flip(grid, r-1, c);
    flip(grid, r+1, c);
    flip(grid, r, c-1);
    flip(grid, r, c+1);
}

bool solve(vector<vector<int>>& grid) {
    vector<vector<int>> result(10, vector<int>(10, 0));
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 10; ++c) {
            if (grid[r][c] == 1) {
                toggle(grid, r+1, c);
                result[r][c] = 1;
            }
        }
    }
    for (int c = 0; c < 10; ++c) {
        if (grid[9][c] == 1) return false;
    }
    for (int r = 0; r < 10; ++r) {
        for (int c = 0; c < 10; ++c) {
            cout << result[r][c] << (c == 9 ? "\n" : " ");
        }
    }
    return true;
}

int main() {
    int n;
    cin >> n;
    while (n--) {
        vector<vector<int>> grid(10, vector<int>(10));
        for (int r = 0; r < 10; ++r) {
            for (int c = 0; c < 10; ++c) {
                cin >> grid[r][c];
            }
        }
        solve(grid);
        if (n) cout << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Flower {
    int x, y;
    double radius;
    double start_angle, end_angle;
};

struct Point {
    int x, y;
};

double to_rad(int deg) {
    return deg * M_PI / 180.0;
}

bool is_inside_sector(const Point& p, const Flower& flower) {
    double dx = p.x - flower.x;
    double dy = p.y - flower.y;
    double dist = sqrt(dx * dx + dy * dy);
    if (dist > flower.radius) return false;

    double angle = atan2(dy, dx);
    if (angle < 0) angle += 2 * M_PI;

    double start = flower.start_angle, end = flower.end_angle;
    if (start > end) start -= 2 * M_PI;

    if (angle > end) angle -= 2 * M_PI;

    return start <= angle && angle <= end;
}

