long long solve(int mask, int last) {
    if (__builtin_popcount(mask) == m) return 0;
    long long &ret = dp[mask][last];
    if (ret != -1) return ret;
    ret = 0;
    for (int i = 0; i < n; ++i) {
        if ((mask & (1 << i)) == 0) {
            long long cur = a[i] + solve(mask | (1 << i), i);
            for (auto &[y, c] : rules[i]) {
