        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    memset(up, -1, sizeof(up));
    preprocess(0, -1);
    cin >> q;
    while(q--){
        int u;
        double p;
        cin >> u >> p;
        prob[u] = p;
        cout << fixed << setprecision(5) << expectedComponents() << '\n';
    }
}

