            }
            else{
                dp[i] = dp[i-1] * 200 % MOD;
            }
        }
        dp[i] %= MOD;
    }
    for(int i=n-2;i>=0;i--){
        if(a[i] != -1){
            if(a[i+1] != -1){
                if(a[i] > a[i+1]) dp[i] = 0;
                else dp[i] = min(dp[i],dp[i+1]);
            }
            else{
                dp[i] = min(a[i],200) - 1 + dp[i+1];
                if(a[i] == 200) dp[i] -= 1;
            }
        }
        else{
            if(a[i+1] != -1){
                ll add = dp[i+1] * (200 - a[i+1]) % MOD;
                dp[i] = (dp[i] + add) % MOD;
            }
            else{
                ll add = dp[i+1] * 200 % MOD;
                dp[i] = (dp[i] * 200 % MOD + add) % MOD;
            }
        }
        dp[i] %= MOD;
    }
    cout << dp[0];
}

