        int u,v;
        cin >> u >> v;
        u--,v--;
        dis[u].push_back(v);
        dis[v].push_back(u);
    }
    int ans=0;
    for(int mask=0;mask<(1<<n);mask++){
        if(valid(mask)){
            ans=max(ans,__builtin_popcount(mask));
        }
    }
