    int root = -1;
    for(int i = 0; i < n; ++i){
        if(a[i] == i+1) root = i;
        else degree[a[i]]++;
    }
    if(root == -1){
        root = 0;
        a[root] = root+1;
        degree[root+1]++;
    }
    int changes = 0;
    deque<int> leaves;
    for(int i = 1; i <= n; ++i){
