            if(degree[new_parent] == 0){
                leaves.push_front(new_parent);
            }
            degree[a[leaf-1]]--;
            degree[new_parent]++;
            a[leaf-1] = new_parent;
            changes++;
        }
    }
    cout << changes << "\n";
    for(int i = 0; i < n; ++i){
