    A = -dy;
    B = dx;
    C = -(A*A + B*B);
    int n;
    cin >> n;
    for(int i = 0;i < n; i++) cin >> X[i] >> Y[i] >> A0[i] >> W[i];
    int k;
    cin >> k;
    ld lo = 0, hi = 1e6;
    for(int iter = 0;iter < 100; iter++){
        ld mid = (lo + hi) / 2;
        if(can(mid, k, n)) hi = mid;
        else lo = mid;
    }
    cout << fixed << setprecision(9) << hi;
}

