    for(int i = 0; i < n; ++i){
        if(!visited[i]){
            auto shapes = getSubtreeShapes(i);
            auto uniqueCount = memo.size();
            if(uniqueCount > maxUnique){
                maxUnique = uniqueCount;
                best = i;
            }
