bool isShichiGoSan(int n) {
    bool has3 = false, has5 = false, has7 = false;
    while (n > 0) {
        int d = n % 10;
        if (d == 3) has3 = true;
        else if (d == 5) has5 = true;
        else if (d == 7) has7 = true;
        else return false;
        n /= 10;
    }
    return has3 && has5 && has7;
}

int countShichiGoSan(int N) {
    int count = 0;
    for (int i = 1; i <= N; ++i) {
        if (isShichiGoSan(i)) {
            ++count;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;
    cout << countShichiGoSan(N) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int H, W;
    cin >> H >> W;
    vector<string> s(H);
    for(int i=0; i<H; i++) cin >> s[i];

    vector<vector<int>> seen(H, vector<int>(W, 0));
    queue<pair<int, int>> q;

    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            if(s[i][j] == '#' && !seen[i][j]){
                q.push({i, j});
                seen[i][j] = 1;
                while(!q.empty()){
                    auto [x, y] = q.front();
                    q.pop();
                    if(x-1 >= 0 && s[x-1][y] == '#' && !seen[x-1][y]){
                        q.push({x-1, y});
                        seen[x-1][y] = 1;
                    }
                    if(x+1 < H && s[x+1][y] == '#' && !seen[x+1][y]){
                        q.push({x+1, y});
                        seen[x+1][y] = 1;
                    }
                    if(y-1 >= 0 && s[x][y-1] == '#' && !seen[x][y-1]){
                        q.push({x, y-1});
                        seen[x][y-1] = 1;
                    }
                    if(y+1 < W && s[x][y+1] == '#' && !seen[x][y+1]){
                        q.push({x, y+1});
                        seen[x][y+1] = 1;
                    }
                }
            }
        }
    }

    bool possible = true;
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            if(s[i][j] == '#' && !seen[i][j]){
                possible = false;
                break;
            }
        }
        if(!possible) break;
    }

    cout << (possible ? "Yes" : "No");
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Node {
    ll open_match, close_match, open_plus, close_plus;
    Node() : open_match(0), close_match(0), open_plus(0), close_plus(0) {}
};

Node merge(Node l, Node r) {
    Node res;
    res.open_plus = l.open_plus + r.open_plus + l.open_match - min(l.open_match, r.close_plus);
    res.close_plus = l.close_plus + r.close_plus + r.close_match - min(r.close_match, l.open_plus);
    res.open_match = l.open_match + r.open_match + min(l.open_plus, r.close_plus);
    res.close_match = l.close_match + r.close_match + min(r.open_plus, l.close_plus);
    return res;
}

void pull(vector<Node> &tree, int v) {
    tree[v] = merge(tree[2*v], tree[2*v+1]);
}

void build(vector<Node> &tree, int v, int tl, int tr, vector<pair<ll, ll>> &a) {
    if (tl == tr) {
        tree[v].open_plus = a[tl].second;
        tree[v].close_plus = -a[tl].second;
        tree[v].open_match = tree[v].close_match = a[tl].first;
        return;
    }
    int tm = (tl + tr) / 2;
    build(tree, 2*v, tl, tm, a);
    build(tree, 2*v+1, tm+1, tr, a);
    pull(tree, v);
}

void update(vector<Node> &tree, int v, int tl, int tr, int pos, ll x, ll y) {
    if (tl == tr) {
        tree[v].open_plus = y;
        tree[v].close_plus = -y;
        tree[v].open_match = tree[v].close_match = x;
        return;
    }
    int tm = (tl + tr) / 2;
    if (pos <= tm) {
        update(tree, 2*v, tl, tm, pos, x, y);
    } else {
        update(tree, 2*v+1, tm+1, tr, pos, x, y);
    }
    pull(tree, v);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, Q;
    cin >> N >> Q;
    int sz = 2 * N;
    vector<pair<ll, ll>> a(sz);
    for(int i=0;i<sz;i++)cin>>a[i].first;
    for(int i=0;i<sz;i++)cin>>a[i].second;
    vector<Node> tree(4*sz);
    build(tree, 1, 0, sz-1, a);
    while(Q--){
        int p;
        ll x, y;
        cin >> p >> x >> y;
        --p;
        update(tree, 1, 0, sz-1, p, x, y);
        cout << tree[1].open_match+tree[1].close_match+tree[1].open_plus+tree[1].close_plus << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

typedef pair<int, int> pii;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<pii> X(N), Y(N);
    for(int i=0;i<N;i++){
        cin >> X[i].first >> Y[i].first;
        X[i].second = i;
        Y[i].second = i;
    }
    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());

    vector<tuple<int, int, int>> edges;
    for(int i=0;i<N-1;i++){
        edges.emplace_back(abs(X[i+1].first - X[i].first), X[i].second, X[i+1].second);
        edges.emplace_back(abs(Y[i+1].first - Y[i].first), Y[i].second, Y[i+1].second);
    }
    sort(edges.begin(), edges.end());

    int uf[N];
    iota(uf, uf+N, 0);
    function<int(int)> find = [&](int x){ return uf[x]==x?x:uf[x]=find(uf[x]); };

    int ans = 0, cnt = 0;
    for(auto [w, u, v] : edges){
        int pu = find(u), pv = find(v);
        if(pu != pv){
            uf[pu] = pv;
            ans += w;
            if(++cnt == N-1) break;
        }
    }
    cout << ans;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int MAXN = 105;

int N, M;
vector<pair<int, int>> adj[MAXN];
int dist[MAXN][MAXN];

void floydWarshall() {
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (i == j) {
                dist[i][j] = 0;
            } else {
                dist[i][j] = INF;
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (auto &e : adj[i]) {
            int j = e.first, w = e.second;
            dist[i][j] = dist[j][i] = min(dist[i][j], w);
        }
    }
    for (int k = 1; k <= N; ++k) {
        for (int i = 1; i <= N; ++i) {
            for (int j = 1; j <= N; ++j) {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

int main() {
    cin >> N >> M;
    for (int i = 0; i < M; ++i) {
        int a, b, c;
        cin >> a >> b >> c;
        adj[a].emplace_back(b, c);
        adj[b].emplace_back(a, c);
    }
    floydWarshall();
    int ans = 0;
    for (int i = 1; i <= N; ++i) {
        for (auto &e : adj[i]) {
            int j = e.first, w = e.second;
            if (dist[i][j] != w) {
                ans++;
            }
        }
    }
    ans /= 2;
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    long long N, M, K;
    cin >> N >> M >> K;
    long long total = (N + M + K);
    long long ans = (3 * mod_pow(3, total - 1) - 2 * mod_pow(2, total) + mod_pow(1, total)) % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << '\n';
}
